def __apply_defaults_for_syslog(cfg):
    syslog = cfg.get("syslog", {})
    additional_vms_config = {
        "vm%d"
        % i: {
            "enb": syslog.get("vm%d" % i, {}).get("enb", defaults.SYSLOG_ENB_STATUS),
            "enb_ip": syslog.get("vm%d" % i, {}).get("enb_ip", defaults.SYSLOG_ENB_IP),
            "ue_sim": syslog.get("vm%d" % i, {}).get(
                "ue_sim", defaults.SYSLOG_UE_SIM_STATUS
            ),
            "ue_sim_ip": syslog.get("vm%d" % i, {}).get(
                "ue_sim_ip", defaults.SYSLOG_UE_SIM_IP
            ),
        }
        for i in range(1, MAX_SUPPORTED_VMs + 1)
    }
    cfg.update(
        {
            "syslog": merge_dicts(
                __create_defaults_for_plugin("syslog", cfg, "compress"),
                additional_vms_config,
            )
        }
    )


def __apply_defaults_for_tti_trace(cfg):
    cfg.update({"tti_trace": __create_defaults_for_plugin("tti_trace", cfg, "cells")})


def __apply_defaults_for_ue_sim(cfg):
    ue_sim = cfg.get("ue_sim", {})
    iphy_keys = ["egate_host", "egate_port", "proxy", "sosreport"]
    cus_keys = ["executor_ip", "executor_port", "sosreport"]
    cfg.update(
        {
            "ue_sim": merge_dicts(
                __create_defaults_for_plugin("ue_sim", cfg),
                {"iphy": __create_defaults_for_plugin("iphy", ue_sim, *iphy_keys)},
                {"cus": __create_defaults_for_plugin("cus", ue_sim, *cus_keys)},
                {"airphone": __create_defaults_for_plugin("airphone", ue_sim)},
            )
        }
    )


def __apply_defaults_for_wireshark(cfg):
    keys = ["m3", "rrc", "s1", "x2", "sctp"]
    cfg.update({"wireshark": __create_defaults_for_plugin("wireshark", cfg, *keys)})


def _remove_plugins_from_cfg(cfg, *plugins):
    for plugin in plugins:
        try:
            del cfg[plugin]
        except KeyError:
            pass


def _api_ver_2_20_0(cfg: dict[str, Any]) -> None:
    old_emil_data = cfg["emil"]
    if old_emil_data["active"] is False:
        new_emil_config = {"active": False}
    else:
        emil_for_bts = {}
        for vm_no in range(1, MAX_SUPPORTED_VMs + 1):
            emil_for_bts[f"vm{vm_no}"] = {
                "profiles": defaults.EMIL_PROFILES,
                "stop_docker": defaults.EMIL_STOP_DOCKER,
                "bts_ip": f"10.0.1.{vm_no * 2}",
            }
        new_emil_config = {"active": True, **emil_for_bts}
    cfg["emil"] = new_emil_config


